function render(){document.title=`${page} · Klarwerk`;$('#crumb').textContent=page;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const views={'Übersicht':dashboard,'Rechnungen':()=>documentList('invoice'),'Angebote':()=>documentList('quote'),'Belege & Ausgaben':expenses,'Kunden':clients,'Steuern':taxes,'Banking':banking,'Wissensassistent':assistant,'Exporte':exportsView,'Vorlagen':templatesView,'Einstellungen':settings,'Hilfe & Recht':legal};$('#app').innerHTML=(views[page]||dashboard)();enhanceInputs($('#app'));if(page==='Vorlagen')updateTemplatePreview()}
function docTotals(d){const items=d.items||[{qty:1,price:d.net||0,vat:d.vat||0}];let taxes={},net=0;for(const x of items){let n=Math.round(x.qty*x.price);net+=n;let r=d.small?0:Number(x.vat);taxes[r]=(taxes[r]||0)+Math.round(n*r/100)}const vat=Object.values(taxes).reduce((a,b)=>a+b,0);return{net,vat,gross:net+vat,taxes}}
function paidTotal(d){return(d.payments||[]).reduce((s,p)=>s+p.amount,0)}
function outstanding(d){return Math.max(0,docTotals(d).gross-paidTotal(d))}
function totals(from='',to='9999'){let income=0,output=0,expense=0,input=0;for(const d of db.invoices){const t=docTotals(d);for(const p of d.payments||[]){if(p.date<from||p.date>to)continue;income+=Math.round(p.amount*t.net/t.gross);output+=p.amount-Math.round(p.amount*t.net/t.gross)}}for(const x of db.expenses){const date=x.paymentDate||(x.paid?x.date:'');if(!date||date<from||date>to)continue;expense+=x.net;input+=x.gross-x.net}return{income,expenses:expense,profit:income-expense,open:db.invoices.filter(d=>d.status==='Offen').reduce((s,d)=>s+outstanding(d),0),vat:output-input,output,input}}
function dashboard(){const t=totals();return title('Deine Finanzen. Im Blick.','Dein Arbeitsbereich für Dokumente, Belege und Zahlungen.','<button onclick="documentForm(\'quote\')">＋ Angebot erstellen</button>'+addInvoice)+`<section class="hero"><div><div class="eyebrow">MEHR ZEIT FÜR DEIN BUSINESS</div><h2>Deine Leistung verdient einen guten Auftritt.</h2><p>Rechnungen und Angebote in deinem Design.<br>Logo hochladen, Vorlage gestalten und direkt loslegen.</p><button style="margin-top:15px" onclick="go('Vorlagen')">Meine Vorlagen gestalten →</button></div><div class="hero-art" aria-hidden="true"><div class="paper"></div><div class="coin">€</div></div></section><div class="stats">${[['Einnahmen',t.income,'Zahlungseingänge, netto'],['Ausgaben',t.expenses,'Bezahlte Ausgaben, netto'],['Überschuss',t.profit,'Vereinfachte Zahlungsübersicht'],['Offene Rechnungen',t.open,'Restbeträge, brutto']].map(([l,n,s])=>`<section class="card"><div class="statlabel">${l}</div><div class="number">${money(n)}</div><small>${s}</small></section>`).join('')}</div><div class="grid"><section class="card"><div class="cardhead"><h2>Die letzten sechs Monate</h2><span class="badge gray">Zahlungen, netto</span></div><div class="legend"><span><i></i>Einnahmen</span><span><i class="light"></i>Ausgaben</span></div>${chart()}</section><section class="card"><h2>Deine nächsten Schritte</h2>${[['Rechnungen',`${db.invoices.filter(d=>d.status==='Offen').length} offene Rechnungen prüfen`],['Belege & Ausgaben',`${db.expenses.filter(x=>!x.asset).length} Ausgaben ohne gespeicherte Belegdatei`],['Banking',`${db.transactions.filter(x=>!x.match).length} Bankumsätze zuordnen`],['Vorlagen','Dein Firmenlogo und Briefpapier einrichten']].map(([p,l])=>`<div class="task" role="button" tabindex="0" onclick="go('${p}')" onkeydown="if(event.key==='Enter')go('${p}')"><span class="taskicon">↗</span>${l}<span class="arrow">→</span></div>`).join('')}</section></div><section class="card"><div class="cardhead"><h2>Letzte Rechnungen</h2><button onclick="go('Rechnungen')">Alle ansehen →</button></div>${invoiceTable(db.invoices.slice(0,5))}</section><div class="notice">Kontodaten werden zentral gespeichert; der Status oben zeigt ausstehende Änderungen. Sichere deine Daten zusätzlich unter „Exporte“. Keine ELSTER-Übermittlung und kein GoBD-Archiv.</div>`}
function chart(){let now=new Date(today()+'T12:00:00');const arr=Array.from({length:6},(_,i)=>{let d=new Date(now.getFullYear(),now.getMonth()-5+i,1,12);let from=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01',end=new Date(d.getFullYear(),d.getMonth()+1,0,12);return{label:d.toLocaleDateString('de-DE',{month:'short'}),...totals(from,end.toLocaleDateString('sv-SE'))}}),max=Math.max(100,...arr.flatMap(t=>[t.income,t.expenses]));return `<div class="chart"><div class="scale"><span>${money(max)}</span><span>${money(max/2)}</span><span>0 €</span></div><div class="bars">${arr.map(t=>`<div class="month"><div class="bar" style="height:${t.income/max*90}%" title="${money(t.income)}"></div><div class="bar light" style="height:${t.expenses/max*90}%" title="${money(t.expenses)}"></div><span>${t.label}</span></div>`).join('')}</div></div>`}
function getDoc(key){return [...db.invoices,...db.quotes].find(x=>x.key===key||x.id===key)}
function invoiceTable(rows){return `<div class="tablewrap"><table><thead><tr><th>KUNDE / DOKUMENT</th><th>DATUM</th><th>STATUS</th><th class="amount">BRUTTO</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td><div class="client"><span class="avatar">${esc(d.client.slice(0,2).toUpperCase())}</span><div>${esc(d.client)}<small>${esc(d.id)} · ${esc(d.items[0]?.desc||'')}</small></div></div></td><td>${date(d.date)}</td><td><span class="badge ${d.status==='Offen'?'orange':d.status==='Entwurf'?'gray':''}">${esc(d.status)}</span>${d.status==='Offen'?`<span class="payment-pill">${d.due<today()?'Überfällig · ':''}Rest ${money(outstanding(d))}</span>`:''}</td><td class="amount">${money(docTotals(d).gross)}</td><td><button onclick="detail('${d.key}')">Öffnen ↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Noch keine passenden Dokumente.</td></tr>'}</tbody></table></div>`}
function documentList(kind){const quotes=kind==='quote',list=quotes?db.quotes:db.invoices;let rows=list.filter(x=>(x.client+' '+x.id).toLowerCase().includes(filter.toLowerCase())&&(statusFilter==='Alle'||x.status===statusFilter));return title(quotes?'Deine Angebote':'Deine Rechnungen',quotes?'Vom ersten Angebot zum nächsten Auftrag.':'Erstellen, prüfen, ausgeben und Zahlungen erfassen.',`<button onclick="go('Vorlagen')">◈ Vorlage gestalten</button><button class="primary" onclick="documentForm('${kind}')">＋ ${quotes?'Angebot':'Rechnung'} erstellen</button>`)+`<div class="toolbar"><input name="search" type="search" aria-label="Dokument suchen" placeholder="Kunde oder Dokumentnummer suchen …" value="${esc(filter)}" oninput="searchRows(this.value)"><select name="status" style="width:180px" aria-label="Status filtern" onchange="statusFilter=this.value;render()">${['Alle','Entwurf',...(quotes?['Angeboten','Angenommen','Abgelehnt']:['Offen','Bezahlt','Storniert'])].map(x=>`<option ${x===statusFilter?'selected':''}>${x}</option>`).join('')}</select></div><section class="card">${invoiceTable(rows)}</section><div class="notice">Druck/PDF nutzt deine eigene Vorlage. Es entsteht keine strukturierte XRechnung oder ZUGFeRD-Datei. Prüfe vor der Ausgabe, welches Format dein Kunde benötigt.</div>`}
function searchRows(v){filter=v;let pos=document.activeElement.selectionStart;render();let el=$('[name=search]');el.focus();el.setSelectionRange(pos,pos)}
function invoiceForm(){documentForm('invoice')}
function lineHTML(x={},i=0){return `<div class="line-row" data-line><div>${field('Leistung','desc','text',x.desc||'','required maxlength="500"')}</div><div>${field('Menge','qty','number',x.qty||1,'required min="0.001" max="100000" step="0.001" oninput="updateDocSum()"')}</div><div>${field('Einheit','unit','text',x.unit||'Stück','required maxlength="30"')}</div><div>${field('Netto / Einheit (€)','price','number',((x.price||0)/100).toFixed(2),'required min="0.01" max="9999999" step="0.01" oninput="updateDocSum()"')}</div><div>${selectField('USt.','vat',[[19,'19 %'],[7,'7 %'],[0,'§ 19']],x.vat??19).replace('<select ','<select onchange="updateDocSum()" ')}</div><button class="remove" type="button" aria-label="Position entfernen" onclick="removeLine(this)">×</button></div>`}
function documentForm(kind='invoice',key){let x=key?getDoc(key):null;if(x?.status!=='Entwurf'&&x){toast('Freigegebene Dokumente können nicht bearbeitet werden.');return}if(!db.clients.length){toast('Bitte zuerst einen Kunden anlegen.');go('Kunden');return}const isQuote=kind==='quote';showModal((x?'Bearbeiten: ':'Neu: ')+(isQuote?'Angebot':'Rechnung'),`<p class="subtle">Inländische Standardleistungen · Sonderfälle separat prüfen. Alle Beträge in EUR.</p><div class="form-grid"><div>${selectField('Kunde','client',db.clients.map(c=>[c.name,c.name]),x?.client||db.clients[0].name)}</div><div>${field(isQuote?'Angebotsdatum':'Rechnungsdatum','date','date',x?.date||today(),'required')}</div><div>${field(isQuote?'Geplantes Leistungsdatum':'Leistungsdatum','service','date',x?.service||today(),'required')}</div><div>${field(isQuote?'Angebot gültig bis':'Zahlbar bis','due','date',x?.due||addDays(today(),14),'required')}</div></div><div class="checkbox-line"><input id="doc-small" name="small" type="checkbox" ${(x?.small??db.profile.small)?'checked':''} onchange="updateDocSum()"><label for="doc-small">Steuerbefreiung als Kleinunternehmer (§ 19 UStG)</label></div><div class="line-editor"><h3>Deine Positionen</h3><div id="lines">${(x?.items||[{qty:1,price:0,vat:19}]).map(lineHTML).join('')}</div><button type="button" onclick="addLine()">＋ Position hinzufügen</button><div class="doc-sum" id="doc-sum"></div></div>${textField('Zusatztext','note',x?.note||'')}<div class="notice">Deine ${isQuote?'Angebots':'Rechnungs'}vorlage wird bei der Freigabe übernommen. Entwürfe kannst du jederzeit bearbeiten.</div>`,f=>{let small=f.has('small'),items=collectLines();if(items.some(i=>i.vat===0)&&!small)throw Error('0 % ist hier nur für § 19 vorgesehen. Aktiviere die Kleinunternehmerregelung oder wähle 7 / 19 %.');if(f.get('due')<f.get('date'))throw Error('Das Fristdatum darf nicht vor dem Ausstellungsdatum liegen.');let d={...(x||{}),key:x?.key||uid(),id:x?.id||'ENTWURF-'+uid().slice(0,8),kind,client:f.get('client'),date:f.get('date'),service:f.get('service'),due:f.get('due'),small,items:items.map(i=>({...i,vat:small?0:i.vat})),note:f.get('note').trim(),status:'Entwurf',payments:[],templateType:isQuote?'quote':'invoice'};Object.assign(d,{net:docTotals(d).net,vat:small?0:d.items[0].vat,desc:d.items[0].desc});const list=isQuote?db.quotes:db.invoices;if(x)list[list.findIndex(i=>i.key===x.key)]=d;else list.unshift(d);if(save((isQuote?'Angebots':'Rechnungs')+'entwurf gespeichert')){$('#modal').close();toast('Entwurf gespeichert')}},'Entwurf speichern',true);updateDocSum()}
function addLine(){const lines=$('#lines');if(lines.children.length>=40){toast('Maximal 40 Positionen pro Dokument.');return}lines.insertAdjacentHTML('beforeend',lineHTML());fixLineIDs();enhanceInputs(lines);updateDocSum()}
function fixLineIDs(){document.querySelectorAll('[data-line]').forEach((row,i)=>row.querySelectorAll('input,select').forEach(el=>{let lab=row.querySelector('label[for="'+el.id+'"]');el.id='line-'+i+'-'+el.name;if(lab)lab.htmlFor=el.id}))}
function removeLine(b){if($('#lines').children.length<=1){toast('Mindestens eine Position ist erforderlich.');return}b.closest('[data-line]').remove();updateDocSum()}
function collectLines(){return [...document.querySelectorAll('[data-line]')].map(row=>{let v=n=>row.querySelector('[name='+n+']').value;let x={desc:v('desc').trim(),qty:Number(v('qty')),unit:v('unit').trim(),price:Math.round(Number(v('price'))*100),vat:Number(v('vat'))};if(!x.desc||!x.unit||!Number.isFinite(x.qty)||x.qty<=0||!Number.isSafeInteger(x.price)||x.price<=0)throw Error('Bitte alle Positionen vollständig und mit positiven Beträgen ausfüllen.');return x})}
function updateDocSum(){document.querySelectorAll('[data-line] select').forEach(el=>{el.disabled=$('#doc-small').checked});try{let d={items:collectLines(),small:$('#doc-small').checked};$('#doc-sum').textContent='Gesamt: '+money(docTotals(d).gross)}catch{$('#doc-sum').textContent='Positionen vervollständigen'}fixLineIDs();enhanceInputs($('#lines'))}
function snapshot(d){return {seller:structuredClone(db.profile),buyer:structuredClone(db.clients.find(c=>c.name===d.client)),template:structuredClone(db.templates[d.kind==='quote'?'quote':'invoice'])}}
function nextNumber(kind,year){const prefix=kind==='quote'?db.profile.quotePrefix:db.profile.prefix;const bucket=prefix+'-'+year;let n=db.counters[bucket]||0;const used=new Set([...db.invoices,...db.quotes].flatMap(d=>[d.id,d.cancellation?.id]));let id;do{id=bucket+'-'+String(++n).padStart(4,'0')}while(used.has(id));db.counters[bucket]=n;return id}
function detail(key){let d=getDoc(key);if(!d)return;const t=docTotals(d),isQuote=d.kind==='quote';showModal(d.id,`<h3>${esc(d.client)}</h3><div class="status-bar"><span class="badge">${esc(d.status)}</span> · ${date(d.date)} · ${isQuote?'Gültig':'Zahlbar'} bis ${date(d.due)}</div><div class="tablewrap"><table><thead><tr><th>LEISTUNG</th><th>MENGE</th><th>NETTO</th><th>UST.</th></tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.desc)}</td><td>${i.qty} ${esc(i.unit)}</td><td>${money(Math.round(i.qty*i.price))}</td><td>${d.small?0:i.vat} %</td></tr>`).join('')}</tbody></table></div><div class="doc-sum">Gesamt ${money(t.gross)}</div>${!isQuote?`<p>Bezahlt: ${money(paidTotal(d))} · ${d.status==='Storniert'?'Storniert – gegebenenfalls Erstattung erfassen':'Offen: '+money(outstanding(d))}</p>`:''}<div class="buttonrow"><button type="button" onclick="previewDocument('${d.key}')">Vorschau / PDF</button><button type="button" onclick="duplicateDoc('${d.key}')">Duplizieren</button>${d.status==='Entwurf'?`<button type="button" onclick="documentForm('${d.kind}','${d.key}')">Bearbeiten</button><button class="primary" type="button" onclick="releasePrompt('${d.key}')">Prüfen & freigeben</button>`:''}${!isQuote&&d.status==='Offen'?`<button type="button" onclick="paymentForm('${d.key}')">Zahlung erfassen</button><button type="button" onclick="mailDocument('${d.key}',true)">Zahlungserinnerung</button>`:''}${d.status==='Angenommen'?`<button class="primary" type="button" onclick="convertQuote('${d.key}')">In Rechnung übernehmen</button>`:''}${['Angeboten','Angenommen','Abgelehnt'].includes(d.status)?`<button type="button" onclick="quoteStatus('${d.key}','Angenommen')">Angenommen</button><button type="button" onclick="quoteStatus('${d.key}','Abgelehnt')">Abgelehnt</button>`:''}${d.status!=='Entwurf'?`<button type="button" onclick="mailDocument('${d.key}')">E-Mail-Entwurf</button>`:''}${!isQuote&&['Offen','Bezahlt'].includes(d.status)&&d.frozen?`<button type="button" onclick="cancelPrompt('${d.key}')">Stornorechnung erstellen</button>`:''}${d.cancellation?`<button type="button" onclick="previewDocument('${d.key}',true)">Stornorechnung ansehen</button>${paidTotal(d)>0?`<button type="button" onclick="paymentForm('${d.key}',true)">Erstattung erfassen</button>`:''}`:''}${d.status==='Entwurf'?`<button class="danger" type="button" onclick="deleteDraft('${d.key}')">Entwurf entfernen</button>`:''}</div>${!isQuote&&d.payments.length?`<h3>Zahlungsverlauf</h3>${d.payments.map(p=>`<p>${date(p.date)} · ${money(p.amount)}${p.transaction?' · Bankzuordnung':''}</p>`).join('')}`:''}${d.convertedTo?`<p>In Rechnung übernommen: ${esc(getDoc(d.convertedTo)?.id||d.convertedTo)}</p>`:''}`,()=>$('#modal').close(),'Schließen',true)}
function releasePrompt(key){const d=getDoc(key),p=db.profile,c=db.clients.find(c=>c.name===d.client);if(!p.name.trim()||!p.address.trim()||!c?.address?.trim()||(!p.taxid.trim()&&d.kind==='invoice')){toast('Bitte Unternehmensname, Anschriften und für Rechnungen Steuernummer / USt-IdNr. vervollständigen.');go('Einstellungen');$('#modal').close();return}showModal('Dokument prüfen & freigeben',`<p>Das Dokument erhält eine fortlaufende Nummer. Inhalt, Kundendaten und Vorlage werden eingefroren; Änderungen erfolgen danach über neue Dokumente.</p><div class="notice">Unterstützt werden einfache inländische Leistungen. Keine Abschläge, Reverse Charge, EU-/Drittlands- oder sonstigen Steuerfälle. Die Druckdatei ist keine strukturierte E-Rechnung.</div><p><b>${esc(d.client)}</b> · ${money(docTotals(d).gross)} · ${date(d.date)}</p><div class="checkbox-line"><input id="release-terms" name="terms" type="checkbox" required><label for="release-terms">Ich habe Pflichtangaben, Steuerbehandlung und die Zulässigkeit des Ausgabeformats im konkreten Fall geprüft.</label></div>`,()=>{if(d.status!=='Entwurf')throw Error('Dokument wurde bereits freigegeben.');d.id=nextNumber(d.kind,d.date.slice(0,4));d.frozen=snapshot(d);d.status=d.kind==='quote'?'Angeboten':'Offen';d.releasedAt=new Date().toISOString();if(save('Dokument freigegeben: '+d.id)){$('#modal').close();toast('Dokument freigegeben: '+d.id)}},'Freigeben')}
function duplicateDoc(key){let x=getDoc(key),d=structuredClone(x);d.key=uid();d.id='ENTWURF-'+uid().slice(0,8);d.date=today();d.due=addDays(today(),14);d.status='Entwurf';d.payments=[];delete d.frozen;delete d.cancellation;delete d.convertedTo;delete d.releasedAt;(d.kind==='quote'?db.quotes:db.invoices).unshift(d);if(save('Dokument dupliziert'))documentForm(d.kind,d.key)}
function deleteDraft(key){const d=getDoc(key);showModal('Entwurf entfernen',`<p>„${esc(d.id)}“ wird in den Papierkorb verschoben. Du kannst ihn unter Exporte wiederherstellen.</p>`,()=>{db.trash??=[];db.trash.push(structuredClone(d));let list=d.kind==='quote'?db.quotes:db.invoices;list.splice(list.findIndex(x=>x.key===key),1);if(save('Entwurf in Papierkorb verschoben'))$('#modal').close()},'In Papierkorb verschieben')}
function quoteStatus(key,status){let d=getDoc(key);if(!d||d.kind!=='quote'||d.status==='Entwurf')return;d.status=status;if(save('Angebot '+d.id+': '+status))detail(key)}
function convertQuote(key){const x=getDoc(key);if(x.convertedTo){toast('Dieses Angebot wurde bereits übernommen.');detail(x.convertedTo);return}const d={...structuredClone(x),key:uid(),id:'ENTWURF-'+uid().slice(0,8),kind:'invoice',status:'Entwurf',date:today(),due:addDays(today(),14),payments:[],sourceQuote:x.id};delete d.frozen;delete d.releasedAt;db.invoices.unshift(d);x.convertedTo=d.key;if(save('Angebot in Rechnungsentwurf übernommen')){page='Rechnungen';render();documentForm('invoice',d.key)}}
function paymentForm(key,refund=false,transaction){const d=getDoc(key),max=refund?paidTotal(d):outstanding(d);showModal(refund?'Erstattung erfassen':'Zahlung erfassen',`<p>${esc(d.id)} · ${refund?'Maximal zu erstatten':'Offener Restbetrag'}: ${money(max)}</p>${field('Zahlungsdatum','paid','date',transaction?.date||today(),'required')}${field('Betrag (€)','amount','number',((transaction?.amount||max)/100).toFixed(2),`required min="0.01" max="${(max/100).toFixed(2)}" step="0.01"`)}`,f=>{let n=Math.round(Number(f.get('amount'))*100);if(n<=0||n>max)throw Error('Betrag liegt außerhalb des offenen Restbetrags.');d.payments.push({date:f.get('paid'),amount:refund?-n:n,transaction:transaction?.id||null});if(!refund)d.status=outstanding(d)===0?'Bezahlt':'Offen';if(transaction)transaction.match=d.key;if(save(refund?'Erstattung erfasst: '+d.id:'Zahlung erfasst: '+d.id)){$('#modal').close();toast('Zahlung gespeichert')}},'Zahlung speichern')}
function cancelPrompt(key){const d=getDoc(key);showModal('Stornorechnung erstellen',`<p>Die Rechnung ${esc(d.id)} wird vollständig storniert. Eine verknüpfte Stornorechnung erhält eine eigene Nummer. Bereits erfasste Zahlungen bleiben bestehen; Rückzahlungen sind separat zu erfassen.</p>${textField('Grund der Stornierung','note','')}`,f=>{if(d.cancellation)throw Error('Bereits storniert.');d.cancellation={id:nextNumber('invoice',today().slice(0,4)),date:today(),note:f.get('note').trim()};d.status='Storniert';if(save('Stornorechnung erstellt: '+d.cancellation.id)){$('#modal').close();toast('Stornorechnung gespeichert')}},'Vollständig stornieren')}
function mailDocument(key,reminder=false){const d=getDoc(key),buyer=d.frozen?.buyer||db.clients.find(c=>c.name===d.client);let subject=reminder?'Zahlungserinnerung zu '+d.id:(d.kind==='quote'?'Angebot ':'Rechnung ')+d.id;let body=reminder?`Guten Tag,\n\nzu unserer Rechnung ${d.id} vom ${date(d.date)} ist noch ein Betrag von ${money(outstanding(d))} offen. Bitte prüfen Sie den Zahlungsausgleich.\n\nVielen Dank.`:`Guten Tag,\n\nanbei erhalten Sie ${d.kind==='quote'?'unser Angebot':'unsere Rechnung'} ${d.id}.\n\nMit freundlichen Grüßen\n${db.profile.name}`;showModal('E-Mail vorbereiten',`<p>Öffnet dein E-Mail-Programm. Das Dokument wird nicht automatisch angehängt oder versendet. Speichere es zuvor über die Druckvorschau als PDF und füge es dort hinzu.</p><div class="notice">Empfänger: ${esc(buyer?.email||'Keine E-Mail hinterlegt')}<br>Betreff: ${esc(subject)}</div>`,()=>{window.location.href='mailto:'+encodeURIComponent(buyer?.email||'')+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);$('#modal').close()},'E-Mail-Programm öffnen')}
function documentHTML(d,cancel=false){const snap=d.frozen||snapshot(d),s=snap.seller,c=snap.buyer||{},t=snap.template||templateDefault,total=docTotals(d),quote=d.kind==='quote',draft=d.status==='Entwurf',factor=cancel?-1:1,num=cancel?d.cancellation.id:d.id,heading=cancel?'Stornorechnung':quote?'Angebot':'Rechnung';const color=/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#23644d',logo=assetSrc(t.logo),bg=assetSrc(t.background);return `<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${esc(heading+' '+num)}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font:11px Arial,sans-serif;color:#243c32;margin:0}h1{font-size:28px;color:${color};margin:30px 0 20px}p{line-height:1.7;white-space:pre-wrap}.background{position:fixed;inset:-15mm;width:210mm;height:297mm;z-index:-1;object-fit:fill}.body{padding-top:${Math.min(100,Math.max(0,Number(t.top)||20))}mm}.head{min-height:65px;display:flex;justify-content:space-between;flex-direction:${t.layout==='left'?'row-reverse':'row'}}.logo{width:${Math.min(260,Math.max(40,Number(t.logoWidth)||140))}px;max-height:100px;object-fit:contain;object-position:top right}.meta{display:flex;justify-content:space-between;gap:20px;margin:25px 0}table{width:100%;border-collapse:collapse;margin:25px 0}thead{display:table-header-group}th{text-align:left;padding:10px 7px;border-bottom:2px solid ${color};font-size:10px}td{padding:11px 7px;border-bottom:1px solid #e0e4dc;vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}tr{break-inside:avoid}th:not(:first-child),td:not(:first-child){text-align:right}.sum{margin-left:auto;width:58%;break-inside:avoid}.sum td{padding:7px}.total{font-weight:bold;font-size:15px}.foot{border-top:1px solid #ced8c9;margin-top:32px;padding-top:12px;font-size:10px;break-inside:avoid}.draft{background:#fff4de;border:1px solid #d9bf87;padding:12px;font-weight:bold;margin-bottom:15px}.footer{white-space:pre-wrap}</style></head><body>${bg?`<img class="background" src="${bg}" alt="Briefpapier">`:''}<div class="body">${draft?'<div class="draft">ENTWURF – noch nicht freigegeben</div>':''}<div class="head"><div><b>${esc(s.name)}</b><p>${esc(s.address)}${s.email?'\n'+esc(s.email):''}${s.phone?'\n'+esc(s.phone):''}</p></div>${logo?`<img class="logo" src="${logo}" alt="Firmenlogo">`:''}</div><h1>${heading} ${esc(num)}</h1><div class="meta"><p><b>${esc(c.name||d.client)}</b>\n${esc(c.address||'')}</p><p>Ausgestellt: ${date(cancel?d.cancellation.date:d.date)}\n${quote?'Geplante Leistung':'Leistungsdatum'}: ${date(d.service)}\n${quote?'Gültig bis':'Zahlbar bis'}: ${date(d.due)}${s.taxid?'\nSteuernummer / USt-IdNr.: '+esc(s.taxid):''}</p></div>${cancel?`<p>Vollständige Stornierung der Rechnung ${esc(d.id)} vom ${date(d.date)}.\n${esc(d.cancellation.note)}</p>`:`<p>${esc(quote?t.offerText:t.intro)}${d.sourceQuote?'\nBezug: Angebot '+esc(d.sourceQuote):''}</p>`}<table><thead><tr><th>Beschreibung</th><th>Menge</th><th>Einzelpreis netto</th><th>USt.</th><th>Gesamt netto</th></tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.desc)}</td><td>${i.qty} ${esc(i.unit)}</td><td>${money(i.price*factor)}</td><td>${d.small?0:i.vat} %</td><td>${money(Math.round(i.qty*i.price)*factor)}</td></tr>`).join('')}</tbody></table><table class="sum"><tr><td>Summe netto</td><td>${money(total.net*factor)}</td></tr>${d.small?'':Object.entries(total.taxes).map(([rate,n])=>`<tr><td>Umsatzsteuer ${rate} %</td><td>${money(n*factor)}</td></tr>`).join('')}<tr class="total"><td>Gesamtbetrag</td><td>${money(total.gross*factor)}</td></tr></table>${d.small?'<p>Steuerbefreiung für Kleinunternehmer gemäß § 19 UStG.</p>':''}<p>${esc(d.note)}</p>${!quote&&!cancel?`<p>${esc(t.payment)}${s.iban?'\nIBAN: '+esc(s.iban):''}${s.bic?' · BIC: '+esc(s.bic):''}${s.bank?'\n'+esc(s.bank):''}\nVerwendungszweck: ${esc(num)}</p>`:''}<div class="foot"><b>${esc(s.name)}</b><p class="footer">${esc(t.footer)}</p></div></div></body></html>`}
async function previewDocument(key,cancel=false){await assetReady.catch(()=>{});const d=getDoc(key),html=documentHTML(d,cancel);showModal('Dokumentvorschau',`<div class="buttonrow"><button type="button" class="primary" onclick="document.querySelector('#doc-frame').contentWindow.print()">Drucken / PDF speichern</button><button type="button" onclick="downloadDoc('${d.key}',${cancel})">HTML herunterladen</button></div><p class="subtle">Im Druckdialog „Als PDF speichern“ wählen. Hintergrundgrafiken aktivieren, wenn du Briefpapier verwendest. Prüfe das Druckbild bei mehrseitigen Dokumenten.</p><iframe id="doc-frame" title="Dokumentvorschau" style="width:100%;height:65vh;border:1px solid #e1e7dc;margin-top:15px"></iframe>`,()=>$('#modal').close(),'Schließen',true);$('#doc-frame').srcdoc=html}
function downloadDoc(key,cancel=false){let d=getDoc(key);download((cancel?d.cancellation.id:d.id)+'.html',documentHTML(d,cancel),'text/html;charset=utf-8')}
function printInvoice(key){previewDocument(key)}
function templateInputs(t){return `<div class="form-grid"><div class="full">${field('Name der Vorlage','templateName','text',t.name,'required maxlength="100"')}</div><div>${field('Akzentfarbe','color','color',t.color)}</div><div>${selectField('Logoposition','layout',[['right','Rechts'],['left','Links']],t.layout)}</div><div>${field('Logobreite (Pixel)','logoWidth','number',t.logoWidth,'required min="40" max="260"')}</div><div>${field('Oberer Abstand (mm)','top','number',t.top,'required min="0" max="100"')}</div></div><div class="upload-area">${field('Firmenlogo hochladen','logo','file','','accept="image/png,image/jpeg,image/webp"')}<p class="subtle">PNG, JPEG oder WebP · maximal 2 MB</p>${t.logo?'<span class="saved-tag">✓ Ein Logo ist gespeichert</span><button type="button" class="linkbutton" onclick="removeTemplateAsset(\'logo\')">Logo entfernen</button>':''}</div><div class="upload-area">${field('Eigenes Briefpapier / Vorlage als Bild','background','file','','accept="image/png,image/jpeg,image/webp"')}<p class="subtle">Optionales A4-Briefpapier hinter dem Dokumentinhalt. PDF/Word zuvor als Bild exportieren.</p>${t.background?'<span class="saved-tag">✓ Briefpapier gespeichert</span><button type="button" class="linkbutton" onclick="removeTemplateAsset(\'background\')">Briefpapier entfernen</button>':''}</div>${textField(templateType==='quote'?'Angebotseinleitung':'Rechnungseinleitung',templateType==='quote'?'offerText':'intro',templateType==='quote'?t.offerText:t.intro)}${templateType==='invoice'?textField('Zahlungshinweis','payment',t.payment):''}${textField('Fußzeile / Unternehmensangaben','footer',t.footer)}`}
function templatesView(){let t=db.templates[templateType];return title('Deine Vorlagen','Dein Firmenauftritt auf jeder Rechnung und jedem Angebot.')+`<div class="template-tabs"><button class="${templateType==='invoice'?'active':''}" onclick="switchTemplate('invoice')">Rechnungsvorlage</button><button class="${templateType==='quote'?'active':''}" onclick="switchTemplate('quote')">Angebotsvorlage</button></div><div class="template-grid"><section class="card"><form id="template-form" onsubmit="saveTemplate(event)" oninput="updateTemplatePreview()">${templateInputs(t)}<div class="actions"><button type="button" onclick="resetTemplate()">Standard laden</button><button class="primary">Vorlage speichern</button></div><p class="saved-status" id="template-status">Änderungen gelten für neue Freigaben. Freigegebene Dokumente behalten ihre Vorlage.</p></form></section><section><div class="cardhead"><h2>Deine Live-Vorschau</h2><span class="badge gray">Beispieldokument</span></div><div id="template-preview"></div><div class="buttonrow"><button onclick="exportTemplate()">Vorlage exportieren ↓</button><button onclick="copyTemplate()">Für ${templateType==='invoice'?'Angebote':'Rechnungen'} übernehmen</button></div><section class="card">${field('Eigene Klarwerk-Vorlage importieren (JSON)','templateFile','file','','accept="application/json,.json" onchange="importTemplate(this.files[0])"')}<p class="subtle" style="margin-top:12px">Mit Logo und Briefpapier. Für eine vorhandene PDF-/Word-Vorlage kannst du dein Logo separat oder den Briefbogen als Bild hochladen. Beliebige fremde Dokumentlayouts werden nicht automatisch konvertiert.</p></section></section></div>`}
function switchTemplate(kind){templateType=kind;render()}
function readTemplateForm(){let f=new FormData($('#template-form'));let old=db.templates[templateType];return{...old,name:f.get('templateName').trim(),color:f.get('color'),layout:f.get('layout'),logoWidth:Number(f.get('logoWidth')),top:Number(f.get('top')),intro:f.has('intro')?f.get('intro'):old.intro,offerText:f.has('offerText')?f.get('offerText'):old.offerText,payment:f.has('payment')?f.get('payment'):old.payment,footer:f.get('footer')}}
async function saveTemplate(e){e.preventDefault();const f=e.target,b=f.querySelector('button.primary');b.disabled=true;try{let t=readTemplateForm();for(let name of ['logo','background']){const file=f.querySelector('[name='+name+']').files[0];if(file)t[name]=await fileAsset(file,true)}db.templates[templateType]=t;if(save('Vorlage gespeichert: '+t.name))toast('Vorlage einschließlich Firmenlogo gespeichert')}catch(err){toast(err.message)}finally{b.disabled=false}}
function updateTemplatePreview(){if(!$('#template-preview'))return;let t=readTemplateForm();const content=`<div class="template-preview">${assetSrc(t.background)?`<img class="preview-bg" src="${assetSrc(t.background)}" alt="Eigenes Briefpapier">`:''}<div class="paper-content" style="padding-top:${Math.max(0,Math.min(100,t.top))/2}px"><div style="display:flex;justify-content:space-between;flex-direction:${t.layout==='left'?'row-reverse':'row'}"><p><b>${esc(db.profile.name)}</b><br>${esc(db.profile.address)}</p><img class="preview-logo" id="live-logo" alt="Firmenlogo" ${assetSrc(t.logo)?`src="${assetSrc(t.logo)}"`:'style="display:none"'}></div><h2 style="color:${/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#23644d'}">${templateType==='invoice'?'Rechnung RE':'Angebot AN'}-${today().slice(0,4)}-0001</h2><p style="margin-top:20px">Musterkunde GmbH<br>Beispielstraße 12, 10115 Berlin</p><p style="margin-top:25px">${esc(templateType==='invoice'?t.intro:t.offerText)}</p><div class="preview-placeholder"><b>Leistung</b><b>Netto</b></div><div class="preview-placeholder"><span>Deine Leistung · 1 Stück</span><span>1.000,00 €</span></div><div class="preview-placeholder"><span>Umsatzsteuer 19 %</span><span>190,00 €</span></div><div class="preview-placeholder"><b>Gesamt</b><b>1.190,00 €</b></div>${templateType==='invoice'?`<p style="margin-top:25px">${esc(t.payment)}</p>`:''}<p class="preview-footer">${esc(t.footer||'Deine Unternehmensangaben und Kontaktdaten')}</p></div></div>`;$('#template-preview').innerHTML=content;for(const name of ['logo','background']){const file=$('#template-form [name='+name+']')?.files[0];if(file&&/^image\/(png|jpeg|webp)$/.test(file.type)&&file.size<=2*1024*1024){let r=new FileReader();r.onload=()=>{let image=name==='logo'?$('#live-logo'):$('#template-preview .preview-bg');if(!image&&name==='background'){image=document.createElement('img');image.className='preview-bg';$('#template-preview .template-preview').prepend(image)}if(image){image.src=r.result;image.style.display='block'}};r.readAsDataURL(file)}}}
function removeTemplateAsset(name){db.templates[templateType][name]='';if(save('Vorlagenbild entfernt'))toast('Bild aus Vorlage entfernt; freigegebene Dokumente bleiben unverändert.')}
function resetTemplate(){db.templates[templateType]={...templateDefault};if(save('Standardvorlage geladen'))toast('Standardvorlage gespeichert')}
function copyTemplate(){db.templates[templateType==='invoice'?'quote':'invoice']=structuredClone(db.templates[templateType]);if(save('Vorlage für beide Dokumentarten übernommen'))toast('Vorlage übernommen')}
async function exportTemplate(){await assetReady;const t=db.templates[templateType];download('klarwerk-'+templateType+'-vorlage.json',JSON.stringify({format:'klarwerk-template',version:1,type:templateType,template:t,assets:[t.logo,t.background].filter(Boolean).map(id=>assets.get(id)).filter(Boolean)},null,2),'application/json')}
function validateAsset(x){return x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.data==='string'&&x.data.length<15*1024*1024&&/^data:(image\/(png|jpeg|webp)|application\/(pdf|xml|octet-stream)|text\/xml);base64,[A-Za-z0-9+/=\s]+$/.test(x.data)}
function safeTemplate(t){if(!t||typeof t.name!=='string'||!/^#[0-9a-f]{6}$/i.test(t.color)||!['left','right'].includes(t.layout))throw Error('Die Datei enthält keine gültige Klarwerk-Vorlage.');const o={...templateDefault};for(const k of ['name','logo','background','intro','footer','payment','offerText']){if(typeof t[k]==='string')o[k]=t[k].slice(0,k==='logo'||k==='background'?100:5000)}o.color=t.color;o.layout=t.layout;o.logoWidth=Math.min(260,Math.max(40,Number(t.logoWidth)||140));o.top=Math.min(100,Math.max(0,Number(t.top)||20));return o}
async function importTemplate(file){try{if(!file)return;if(file.size>8*1024*1024)throw Error('Vorlagendatei maximal 8 MB.');const data=JSON.parse(await file.text());if(data.format!=='klarwerk-template')throw Error('Bitte eine aus Klarwerk exportierte JSON-Vorlage verwenden.');const t=safeTemplate(data.template);for(const a of data.assets||[]){if(!validateAsset(a)||!/^data:image\/(png|jpeg|webp);base64,/.test(a.data))throw Error('Ungültiges Vorlagenbild.')}const mapping={};for(const a of data.assets||[]){let id=uid();mapping[a.id]=id;await putAsset({...a,id})}t.logo=mapping[t.logo]||'';t.background=mapping[t.background]||'';db.templates[templateType]=t;if(save('Eigene Vorlage importiert'))toast('Vorlage mit Firmenbildern importiert')}catch(e){toast(e.message||'Vorlage konnte nicht importiert werden.')}}
function expenses(){return title('Belege & Ausgaben','Originaldateien speichern und Ausgaben nachvollziehen.',addExpense)+`<section class="card"><div class="tablewrap"><table><thead><tr><th>LIEFERANT / AUSGABE</th><th>KATEGORIE</th><th>DATUM / ZAHLUNG</th><th>BELEG</th><th>BRUTTO</th><th></th></tr></thead><tbody>${db.expenses.map(x=>`<tr><td>${esc(x.client)}<small>${esc(x.desc)}</small></td><td>${esc(x.category)}</td><td>${date(x.date)}<small>${x.paid?'Bezahlt '+date(x.paymentDate||x.date):'Offen'}</small></td><td>${x.asset?`<button onclick="openAsset('${x.asset}')">Original herunterladen ↓</button>`:`<span class="badge orange">${esc(x.filename?'Nur alter Dateiname':'Beleg fehlt')}</span>`}</td><td>${money(x.gross)}</td><td><button onclick="expenseForm('${x.key}')">Bearbeiten</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Noch keine Ausgaben erfasst.</td></tr>'}</tbody></table></div></section><div class="notice">Belege werden zentral und im Browsercache gespeichert, nicht in einem revisionssicheren Archiv. Keine OCR oder automatische Prüfung des Vorsteuerabzugs. Nutze Exporte für eine vollständige Sicherung einschließlich Dateien.</div>`}
function expenseForm(key){const x=db.expenses.find(x=>x.key===key);showModal(x?'Ausgabe bearbeiten':'Ausgabe erfassen',`<div class="form-grid"><div>${field('Lieferant','client','text',x?.client||'','required maxlength="150"')}</div><div>${field('Belegdatum','date','date',x?.date||today(),'required')}</div><div class="full">${field('Beschreibung','desc','text',x?.desc||'','required maxlength="500"')}</div><div>${field('Nettobetrag (€)','net','number',x?(x.net/100).toFixed(2):'','required min="0.01" max="99999999" step="0.01"')}</div><div>${selectField('Umsatzsteuer laut Beleg','vat',[[19,'19 %'],[7,'7 %'],[0,'Ohne ausgewiesene USt.']],x?.vat??19)}</div><div>${field('Zahlungsdatum (leer = offen)','paymentDate','date',x?.paymentDate||(x?.paid?x.date:''))}</div><div>${selectField('Kategorie','category',['Software','Arbeitsplatz','Bürobedarf','Reisen','Sonstiges'].map(s=>[s,s]),x?.category||'Sonstiges')}</div><div class="full">${field('Originalbeleg hochladen','receipt','file','','accept=".pdf,.png,.jpg,.jpeg,.webp,.xml"')}${x?.asset?'<p class="subtle">Ein Beleg ist gespeichert. Ein neuer Upload ersetzt die Verknüpfung.</p>':''}</div></div>`,async f=>{const file=f.get('receipt'),asset=file?.size?await fileAsset(file):x?.asset||'';const n=Math.round(Number(f.get('net'))*100),v=Number(f.get('vat')),row={key:x?.key||uid(),id:x?.id||'A-'+uid().slice(0,8),client:f.get('client').trim(),desc:f.get('desc').trim(),net:n,vat:v,gross:n+Math.round(n*v/100),date:f.get('date'),paymentDate:f.get('paymentDate'),paid:!!f.get('paymentDate'),category:f.get('category'),asset,filename:file?.size?file.name:x?.filename||''};if(x)db.expenses[db.expenses.findIndex(a=>a.key===x.key)]=row;else db.expenses.unshift(row);if(save('Ausgabe gespeichert: '+row.client)){$('#modal').close();toast('Ausgabe'+(asset?' und Originalbeleg':'')+' gespeichert')}},'Ausgabe speichern')}
function clients(){return title('Deine Kunden','Kontaktdaten für Rechnungen und Angebote.','<button class="primary" onclick="clientForm()">＋ Kunde anlegen</button>')+`<div class="featuregrid">${db.clients.map((c,i)=>`<section class="card"><span class="avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><h2 style="margin-top:15px">${esc(c.name)}</h2><p>${esc(c.address)}<br>${esc(c.email)}</p><button onclick="clientForm(${i})">Bearbeiten</button></section>`).join('')}</div>`}
function clientForm(i){let x=db.clients[i]||{};showModal(i===undefined?'Kunde anlegen':'Kunde bearbeiten',field('Name / Unternehmen','name','text',x.name||'','required maxlength="150"')+textField('Vollständige Anschrift','address',x.address||'')+field('E-Mail (optional)','email','email',x.email||''),f=>{let n=f.get('name').trim(),a=f.get('address').trim();if(!n||!a)throw Error('Name und vollständige Anschrift sind erforderlich.');if(db.clients.some((c,j)=>j!==i&&c.name===n))throw Error('Dieser Kundenname existiert bereits.');let c={name:n,address:a,email:f.get('email').trim()};if(i===undefined)db.clients.push(c);else{db.invoices.concat(db.quotes).forEach(d=>{if(d.client===x.name&&d.status==='Entwurf')d.client=n});db.clients[i]=c}if(save('Kunde gespeichert: '+n)){$('#modal').close();toast('Kunde gespeichert')}},'Kunde speichern')}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let first=text.split(/\r?\n/)[0],sep=first.includes(';')?';':',',rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV enthält nicht geschlossene Anführungszeichen.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function normalizeDate(s){s=s.trim();let m=s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);if(m)s=m[3]+'-'+m[2]+'-'+m[1];if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||isNaN(new Date(s+'T12:00:00'))||new Date(s+'T12:00:00').toISOString().slice(0,10)!==s)throw Error('Ungültiges Datum: '+s);return s}
function parseEuro(s){s=String(s).trim().replace(/\s|€/g,'');if(s.includes(','))s=s.replaceAll('.','').replace(',','.');if(!/^-?\d+(\.\d{1,2})?$/.test(s))throw Error('Ungültiger Betrag: '+s);let n=Math.round(Number(s)*100);if(!Number.isSafeInteger(n)||!n)throw Error('Betrag muss ungleich null sein.');return n}
function banking(){return title('Banking & Zahlungsabgleich','Bankumsätze importieren und selbst zuordnen.','<button onclick="bankSample()">CSV-Beispiel ↓</button><button class="primary" onclick="bankImportForm()">＋ Umsätze importieren</button>')+`<div class="stats"><section class="card"><div class="statlabel">Importierte Umsätze</div><div class="number">${db.transactions.length}</div><small>Kein Live-Bankzugriff</small></section><section class="card"><div class="statlabel">Noch zuzuordnen</div><div class="number">${db.transactions.filter(t=>!t.match).length}</div><small>Ein- und Ausgänge prüfen</small></section><section class="card"><div class="statlabel">Summe der importierten Umsätze</div><div class="number">${money(db.transactions.reduce((s,t)=>s+t.amount,0))}</div><small>Dies ist kein Kontostand</small></section><section class="card"><div class="statlabel">Verbindung</div><div class="number" style="font-size:20px">CSV / manuell</div><small>Kein Bankanbieter angebunden</small></section></div><section class="card"><div class="tablewrap"><table><thead><tr><th>DATUM</th><th>NAME / VERWENDUNGSZWECK</th><th>BETRAG</th><th>ZUORDNUNG</th></tr></thead><tbody>${db.transactions.map(t=>`<tr><td>${date(t.date)}</td><td>${esc(t.name)}<small>${esc(t.ref)}</small></td><td class="${t.amount<0?'danger':'positive'}">${money(t.amount)}</td><td>${t.match?`<span class="badge">Zugeordnet</span><small>${esc(t.match.startsWith('expense:')?db.expenses.find(e=>'expense:'+e.key===t.match)?.client:getDoc(t.match)?.id||'Dokument')}</small>`:`<button onclick="matchTransaction('${t.id}')">${t.amount>0?'Rechnung':'Ausgabe'} zuordnen</button>`}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Importiere deine Bankumsätze über eine CSV-Datei.</td></tr>'}</tbody></table></div></section><div class="notice">Der Import ändert Zahlungen erst nach deiner Zuordnung. Identische Importzeilen werden bei Wiederholungsimport übersprungen. Kontostände, Überweisungen und Kontoeröffnung sind nicht angebunden.</div>`}
function bankSample(){download('klarwerk-bank-beispiel.csv','\ufeffDatum;Betrag;Name;Verwendungszweck\r\n'+today()+';119,00;Musterkunde;RE-'+today().slice(0,4)+'-0001\r\n'+today()+';-59,50;Bürobedarf;Beleg 123\r\n','text/csv;charset=utf-8')}
function bankImportForm(){showModal('Bankumsätze importieren',`<p>Benötigte Spalten: Datum, Betrag, Name, Verwendungszweck. Du kannst die Spaltenüberschriften deiner Bankdatei in einer Tabellenkalkulation entsprechend anpassen. Maximal 5.000 Zeilen.</p>${field('Bankumsätze (CSV)','bankFile','file','','required accept=".csv,text/csv"')}`,async f=>{let file=f.get('bankFile');if(file.size>5*1024*1024)throw Error('CSV maximal 5 MB.');const rows=parseCSV(await file.text()),head=rows.shift()?.map(s=>s.trim().toLowerCase());if(!head||!['datum','betrag','name','verwendungszweck'].every(s=>head.includes(s)))throw Error('Spalten fehlen. Erwartet: Datum, Betrag, Name, Verwendungszweck.');if(rows.length>5000)throw Error('Maximal 5.000 Zeilen pro Import.');const occ=new Map(),known=new Set(db.transactions.map(t=>t.fingerprint));let skipped=0,staged=rows.map((r,i)=>{try{let v=h=>r[head.indexOf(h)]||'',t={id:uid(),date:normalizeDate(v('datum')),amount:parseEuro(v('betrag')),name:v('name').trim().slice(0,300),ref:v('verwendungszweck').trim().slice(0,1000),match:null};let base=JSON.stringify([t.date,t.amount,t.name,t.ref]);let n=(occ.get(base)||0)+1;occ.set(base,n);t.fingerprint=base+'#'+n;if(known.has(t.fingerprint)){skipped++;return null}return t}catch(e){throw Error('Zeile '+(i+2)+': '+e.message)}}).filter(Boolean);showModal('Import prüfen',`<p>${staged.length} neue Umsätze · ${skipped} bereits vorhandene Zeilen übersprungen.</p><div class="tablewrap"><table><thead><tr><th>DATUM</th><th>NAME</th><th>BETRAG</th></tr></thead><tbody>${staged.slice(0,12).map(t=>`<tr><td>${date(t.date)}</td><td>${esc(t.name)}</td><td>${money(t.amount)}</td></tr>`).join('')}</tbody></table></div>`,()=>{db.transactions.push(...staged);if(save('Bankumsätze importiert: '+staged.length)){$('#modal').close();toast(staged.length+' Umsätze importiert')}},'Import bestätigen')},'Datei prüfen')}
function matchTransaction(id){const tx=db.transactions.find(t=>t.id===id);if(!tx||tx.match)return;const options=tx.amount>0?db.invoices.filter(d=>d.status==='Offen'&&outstanding(d)>=tx.amount).map(d=>[d.key,d.id+' · '+d.client+' · offen '+money(outstanding(d))]):db.expenses.filter(e=>e.gross===-tx.amount&&!db.transactions.some(t=>t.match==='expense:'+e.key)).map(e=>['expense:'+e.key,e.client+' · '+money(e.gross)]);if(!options.length){toast(tx.amount>0?'Keine passende offene Rechnung. Bitte zuerst eine Rechnung freigeben.':'Keine Ausgabe mit passendem Bruttobetrag. Bitte die Ausgabe zuerst erfassen.');if(tx.amount<0)go('Belege & Ausgaben');return}showModal('Bankumsatz zuordnen',`<p>${esc(tx.name)} · ${money(tx.amount)} · ${date(tx.date)}</p><p>${esc(tx.ref)}</p>${selectField(tx.amount>0?'Offene Rechnung':'Vorhandene Ausgabe','match',options,options[0][0])}<div class="notice">Die Zuordnung wird manuell bestätigt. Bei Ausgaben wird der Zahlungstag auf das Datum des Bankumsatzes gesetzt.</div>`,f=>{let key=f.get('match');if(tx.match)throw Error('Dieser Umsatz wurde bereits zugeordnet.');if(tx.amount>0){const d=getDoc(key);if(!d||d.status!=='Offen'||outstanding(d)<tx.amount)throw Error('Rechnung kann diesen Betrag nicht aufnehmen.');d.payments.push({date:tx.date,amount:tx.amount,transaction:tx.id});d.status=outstanding(d)===0?'Bezahlt':'Offen'}else{let e=db.expenses.find(e=>'expense:'+e.key===key);if(!e)throw Error('Ausgabe fehlt.');e.paid=true;e.paymentDate=tx.date}tx.match=key;if(save('Bankumsatz zugeordnet')){$('#modal').close();toast('Zahlung zugeordnet')}},'Zahlung verbindlich zuordnen')}
function reportControls(){return `<form class="toolbar" onsubmit="event.preventDefault();reportFrom=this.elements.from.value;reportTo=this.elements.to.value;if(reportFrom>reportTo){toast('Beginn muss vor Ende liegen.');return}render()"><div>${field('Zeitraum von','from','date',reportFrom,'required')}</div><div>${field('Bis einschließlich','to','date',reportTo,'required')}</div><button style="align-self:end" class="primary">Auswerten</button></form>`}
function taxes(){let t=totals(reportFrom,reportTo);const reserve=Math.round(Math.max(0,t.profit)*db.profile.reserve/100);return title('Steuerunterlagen vorbereiten','Zeiträume auswerten, Rücklagen planen und Unterlagen zusammenstellen.')+reportControls()+`<div class="stats">${[['Zahlungseingänge, netto',t.income],['Bezahlte Ausgaben, netto',t.expenses],['Vereinfachter Überschuss',t.profit],['Rücklagenziel '+db.profile.reserve+' %',reserve]].map(([l,n])=>`<section class="card"><div class="statlabel">${l}</div><div class="number">${money(n)}</div></section>`).join('')}</div><section class="card"><div class="cardhead"><h2>Zahlungsbasierte USt.-Rechenhilfe</h2><button onclick="exportReport()">Zeitraumauswertung ↓</button></div><table><tbody><tr><td>In Zahlungen enthaltene Umsatzsteuer</td><td class="amount">${money(t.output)}</td></tr><tr><td>In bezahlten Ausgaben enthaltene Umsatzsteuer</td><td class="amount">${money(t.input)}</td></tr><tr><td>Rechnerische Differenz</td><td class="amount">${money(t.vat)}</td></tr></tbody></table><p class="subtle" style="margin-top:15px">Keine steuerliche Zahllast: Vorsteuerberechtigung, Ist-/Sollversteuerung, Sonderfälle und zeitliche Abgrenzung werden nicht geprüft. Keine vollständige EÜR oder Steuerberechnung.</p></section><div class="notice">ELSTER ist nicht verbunden. Du kannst Unterlagen und Checklisten vorbereiten. Die App erstellt oder übermittelt keine amtlichen Steuererklärungen.</div><div class="featuregrid">${['Umsatzsteuer-Voranmeldung','Einnahmenüberschussrechnung (EÜR)','Einkommensteuererklärung','Umsatzsteuerjahreserklärung','Gewerbesteuererklärung','Zusammenfassende Meldung'].map((name,i)=>`<section class="card"><span class="badge gray">${(db.taxPrep?.[i]?.done||[]).length} / 3 Prüfschritte</span><h2 style="margin-top:18px">${name}</h2><p>Eigene Prüfliste und Notizen speichern, Unterlagen exportieren.</p><button onclick="taxChecklist(${i})">Vorbereitung öffnen →</button></section>`).join('')}</div>`}
function taxChecklist(i){let names=['Umsatzsteuer-Voranmeldung','EÜR','Einkommensteuer','Umsatzsteuerjahreserklärung','Gewerbesteuer','Zusammenfassende Meldung'],prep=db.taxPrep?.[i]||{done:[],note:''},checks=['Belege und Zahlungseingänge vollständig erfasst','Steuerliche Einordnung und Sonderfälle fachlich geprüft','Übertragung und Einreichung außerhalb dieser App geprüft'];showModal(names[i]+' · Vorbereitung',`<p>Diese Liste dokumentiert deine Vorbereitung. Sie ersetzt keine amtlichen Formulare und löst keine Einreichung aus.</p>${checks.map((s,j)=>`<div class="checkbox-line"><input id="check-${j}" name="check-${j}" type="checkbox" data-help="checklist" ${prep.done.includes(j)?'checked':''}><label for="check-${j}">${s}</label></div>`).join('')}${textField('Eigene Notizen','note',prep.note)}<div class="buttonrow"><button type="button" onclick="exportReport()">Zeitraumauswertung herunterladen</button><a target="_blank" rel="noopener" href="https://www.elster.de/eportal/start">Mein ELSTER öffnen ↗</a></div>`,f=>{db.taxPrep??={};db.taxPrep[i]={done:[0,1,2].filter(j=>f.has('check-'+j)),note:f.get('note')};if(save('Steuervorbereitung gespeichert: '+names[i])){$('#modal').close();toast('Vorbereitung gespeichert')}})}
function exportReport(){const t=totals(reportFrom,reportTo);download('klarwerk-auswertung-'+reportFrom+'-'+reportTo+'.txt',`Klarwerk – vereinfachte Zahlungsübersicht\nZeitraum: ${reportFrom} bis ${reportTo}\nEinnahmen netto: ${money(t.income)}\nAusgaben netto: ${money(t.expenses)}\nÜberschuss netto: ${money(t.profit)}\nUmsatzsteuer in Zahlungen: ${money(t.output)}\nUmsatzsteuer in Ausgaben: ${money(t.input)}\nDifferenz: ${money(t.vat)}\n\nKeine EÜR oder Steuererklärung. Keine Prüfung von Sonderfällen, Vorsteuerberechtigung und zeitlicher Steuerentstehung.`, 'text/plain;charset=utf-8')}
const knowledgeArticles=[{title:'Welche Angaben gehören auf eine Rechnung?',tags:'rechnung pflichtangaben steuernummer anschrift nummer leistung',text:'Prüfe Namen und vollständige Anschriften, Steuernummer oder USt-IdNr., Ausstellungsdatum, eindeutige Rechnungsnummer, Art und Umfang der Leistung, Leistungsdatum und die passende Umsatzsteuerbehandlung. Sonderfälle können zusätzliche Angaben erfordern.',url:'https://www.gesetze-im-internet.de/ustg_1980/__14.html'},{title:'E-Rechnung oder einfache PDF?',tags:'e-rechnung pdf xrechnung zugferd peppol elektronisch',text:'Eine einfache PDF ist keine strukturierte E-Rechnung. Maßgeblich sind die Regeln, Ausnahmen und Übergangsfristen für den konkreten Fall. Die Druckausgabe dieser App erzeugt keine XRechnung oder ZUGFeRD-Datei.',url:'https://www.bundesfinanzministerium.de/Content/DE/FAQ/e-rechnung.html'},{title:'Kleinunternehmerregelung',tags:'kleinunternehmer 19 umsatzsteuer steuerfrei grenze',text:'§ 19 UStG enthält Umsatzgrenzen und weitere Voraussetzungen. Die Auswahl im Profil stellt keine automatische Berechtigungsprüfung dar. Prüfe insbesondere Gründungsfälle und Überschreitungen fachlich.',url:'https://www.gesetze-im-internet.de/ustg_1980/__19.html'},{title:'Was braucht eine ELSTER-Anbindung?',tags:'elster eric übermittlung steuererklärung finanzamt',text:'Hersteller benötigen eine Registrierung, Zugang zum Entwicklerbereich und eine Hersteller-ID. ERiC prüft und übermittelt Steuerdaten. Diese App verfügt derzeit über keine solche Integration.',url:'https://www.elster.de/elsterweb/infoseite/entwickler'},{title:'Wie übernehme ich mein Firmenlogo?',tags:'logo vorlage briefpapier design angebot rechnung import',text:'Öffne Vorlagen, wähle Rechnung oder Angebot und lade PNG, JPEG oder WebP hoch. Speichere die Vorlage. Über „Für Angebote/Rechnungen übernehmen“ nutzt du dasselbe Design für beide. Die Vorlage wird bei neuen Dokumentfreigaben übernommen.',page:'Vorlagen'},{title:'Wie sichere ich meine Belege und Dokumente?',tags:'sicherung export backup belege speichern wiederherstellen daten',text:'Unter Exporte lädt die vollständige Sicherung Dokumente, Firmenangaben, Vorlagen und Originaldateien als JSON herunter. Lagere diese Datei sicher. Browserdaten können verloren gehen. Lokal gespeicherte Daten sind kein GoBD-Archiv.',page:'Exporte'}];
function assistant(){let words=knowledgeQuery.toLowerCase().split(/\s+/).filter(Boolean),rows=knowledgeArticles.filter(a=>!words.length||words.some(w=>(a.title+' '+a.tags+' '+a.text).toLowerCase().includes(w)));return title('Wissen & Hilfe','Konkrete Erklärungen mit Quellen. Keine individuelle Steuerberatung.')+`<section class="card"><form class="knowledge-input" onsubmit="event.preventDefault();knowledgeQuery=this.elements.query.value;render()"><div>${field('Was möchtest du wissen?','query','search',knowledgeQuery,'placeholder="Zum Beispiel: Logo, E-Rechnung, Sicherung …"')}</div><button class="primary">Wissen durchsuchen</button></form><p class="subtle" style="margin-top:15px">Lokale Suche in geprüften Hilfetexten. Kein externer KI-Dienst.</p></section><div class="search-results">${rows.map(a=>`<section class="card"><h2>${a.title}</h2><p style="margin:15px 0">${a.text}</p>${a.url?`<a href="${a.url}" target="_blank" rel="noopener">Offizielle Quelle ↗</a>`:`<button onclick="go('${a.page}')">${a.page} öffnen →</button>`}</section>`).join('')||'<section class="card"><h2>Kein passender Artikel</h2><p>Versuche einen kürzeren Suchbegriff. Für individuelle steuerliche Fragen wende dich an eine befugte Fachperson.</p></section>'}</div>`}
function csv(){const rows=[['Typ','Nummer','Name','Ausstellungsdatum','Zahlungen EUR','Netto EUR','USt EUR','Brutto EUR','Status'],...db.invoices.map(d=>{let t=docTotals(d);return['Rechnung',d.id,d.client,d.date,(paidTotal(d)/100).toFixed(2),(t.net/100).toFixed(2),(t.vat/100).toFixed(2),(t.gross/100).toFixed(2),d.status]}),...db.expenses.map(e=>['Ausgabe',e.id,e.client,e.date,e.paid?(e.gross/100).toFixed(2):'0',(e.net/100).toFixed(2),((e.gross-e.net)/100).toFixed(2),(e.gross/100).toFixed(2),e.paid?'Bezahlt':'Offen'])];const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';download('klarwerk-buchungen.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Buchungen exportiert · kein DATEV-Format')}
async function backup(){try{await assetReady;download('klarwerk-vollstaendige-sicherung-'+today()+'.json',JSON.stringify({format:'klarwerk-backup',version:2,created:new Date().toISOString(),db,assets:[...assets.values()]},null,2),'application/json');toast('Vollständige Sicherung heruntergeladen')}catch(e){toast('Dateisicherung nicht verfügbar: '+e.message)}}
function exportsView(){return title('Deine Daten. In deiner Hand.','Sichern, exportieren und wiederherstellen.')+`<div class="featuregrid"><section class="card"><span class="badge">CSV</span><h2 style="margin-top:20px">Buchungen exportieren</h2><p>Rechnungs- und Ausgabenübersicht als CSV. Kein DATEV-Format.</p><button onclick="csv()">CSV herunterladen ↓</button></section><section class="card"><span class="badge">Vollständige Sicherung</span><h2 style="margin-top:20px">Daten und Dateien</h2><p>Dokumente, Vorlagen, Logos, Briefpapier, Bankumsätze und Originalbelege in einer Datei. Vertraulich aufbewahren.</p><button class="primary" onclick="backup()">Alles sichern ↓</button></section><section class="card"><span class="badge gray">Wiederherstellung</span><h2 style="margin-top:20px">Sicherung laden</h2><p>Ersetzt nach Vorschau und Bestätigung deinen lokalen Arbeitsbereich.</p>${field('Klarwerk-Sicherung (JSON)','restoreFile','file','','accept="application/json,.json" onchange="restoreBackup(this.files[0])"')}</section></div><div class="grid" style="margin-top:24px"><section class="card"><div class="cardhead"><h2>Aktivitäten</h2><button onclick="download('klarwerk-protokoll.json',JSON.stringify(db.log,null,2),'application/json')">Protokoll ↓</button></div>${db.log.slice(0,12).map(x=>`<div class="task"><span class="check">✓</span><div>${esc(x.action)}<small>${new Date(x.at).toLocaleString('de-DE')}</small></div></div>`).join('')||'<p>Noch keine Änderungen.</p>'}<p class="subtle">Veränderbares lokales Protokoll, kein GoBD-Nachweis.</p></section><section class="card"><h2>Papierkorb</h2><p class="subtle" style="margin-top:10px">Entfernte Entwürfe wiederherstellen.</p>${(db.trash||[]).map((d,i)=>`<div class="task"><div>${esc(d.id)}<small>${esc(d.client)}</small></div><button onclick="restoreDraft(${i})">Wiederherstellen</button></div>`).join('')||'<p style="margin-top:20px">Der Papierkorb ist leer.</p>'}</section></div>`}
function restoreDraft(i){const d=db.trash?.[i];if(!d)return;(d.kind==='quote'?db.quotes:db.invoices).unshift(d);db.trash.splice(i,1);if(save('Entwurf wiederhergestellt'))toast('Entwurf wiederhergestellt')}
function validateBackup(data){if(data.format!=='klarwerk-backup'||data.version!==2||!data.db||!Array.isArray(data.assets))throw Error('Bitte eine vollständige Klarwerk-v2-Sicherung auswählen.');const b=data.db;for(const k of ['invoices','quotes','clients','expenses','transactions','log'])if(!Array.isArray(b[k])||b[k].length>50000)throw Error('Ungültige Datenliste: '+k);const text=(x,n=5000)=>typeof x==='string'&&x.length<=n,key=x=>text(x,100)&&/^[\w-]+$/.test(x),num=x=>Number.isSafeInteger(x)&&Math.abs(x)<1e14;if(!b.profile||!text(b.profile.name)||!text(b.profile.address)||!text(b.profile.taxid)||!b.templates)throw Error('Ungültiges Unternehmensprofil.');b.templates.invoice=safeTemplate(b.templates.invoice);b.templates.quote=safeTemplate(b.templates.quote);for(const c of b.clients)if(!text(c.name)||!text(c.address)||!text(c.email))throw Error('Ungültige Kundendaten.');for(const d of [...b.invoices,...b.quotes,...(b.trash||[])]){if(!key(d.key)||!text(d.id,100)||!text(d.client)||!['invoice','quote'].includes(d.kind)||!Array.isArray(d.items)||!d.items.length||d.items.length>40||!Array.isArray(d.payments))throw Error('Ungültiges Dokument.');normalizeDate(d.date);normalizeDate(d.service);normalizeDate(d.due);for(const i of d.items)if(!text(i.desc)||!text(i.unit,100)||!Number.isFinite(i.qty)||i.qty<=0||!num(i.price)||i.price<=0||![0,7,19].includes(i.vat))throw Error('Ungültige Dokumentposition.');for(const p of d.payments){normalizeDate(p.date);if(!num(p.amount))throw Error('Ungültige Zahlung.')}if(d.frozen){d.frozen.template=safeTemplate(d.frozen.template);if(!d.frozen.seller||!d.frozen.buyer)throw Error('Ungültiger Dokumentstand.')}}for(const e of b.expenses){if(!key(e.key)||!text(e.client)||!text(e.desc)||!num(e.net)||!num(e.gross)||!text(e.category)||!normalizeDate(e.date))throw Error('Ungültige Ausgabe.');if(e.asset&&!key(e.asset))throw Error('Ungültige Belegverknüpfung.')}for(const t of b.transactions){if(!key(t.id)||!num(t.amount)||!text(t.name)||!text(t.ref)||!text(t.fingerprint))throw Error('Ungültiger Bankumsatz.');normalizeDate(t.date);if(t.match&&!/^(expense:)?[\w-]+$/.test(t.match))throw Error('Ungültige Bankzuordnung.')}for(const a of data.assets)if(!key(a.id)||!validateAsset(a))throw Error('Ungültige Datei in Sicherung.');const ids=new Set(data.assets.map(a=>a.id));for(const t of [b.templates.invoice,b.templates.quote,...b.invoices.map(d=>d.frozen?.template),...b.quotes.map(d=>d.frozen?.template)].filter(Boolean))for(const id of [t.logo,t.background].filter(Boolean))if(!ids.has(id))throw Error('Ein Vorlagenbild fehlt in der Sicherung.');for(const e of b.expenses)if(e.asset&&!ids.has(e.asset))throw Error('Eine Belegdatei fehlt in der Sicherung.');return b}
async function restoreBackup(file){try{if(!file)return;if(file.size>80*1024*1024)throw Error('Sicherungsdatei maximal 80 MB.');const payload=JSON.parse(await file.text()),b=validateBackup(payload);showModal('Sicherung wiederherstellen',`<p>${b.invoices.length} Rechnungen · ${b.quotes.length} Angebote · ${b.expenses.length} Ausgaben · ${payload.assets.length} Dateien</p><div class="notice">Der aktuelle Arbeitsbereich wird ersetzt. Zur Sicherheit wird der bisherige Datenstand vorher als JSON heruntergeladen. Diese Aktion betrifft ausschließlich Daten in diesem Browser.</div>`,async()=>{await backup();for(const a of payload.assets)await putAsset(a);const old=db;b.revision=db.revision||0;db=b;if(!persist('Datensicherung wiederhergestellt')){db=old;throw Error('Wiederherstellung nicht gespeichert.')}$('#modal').close();render();toast('Arbeitsbereich wiederhergestellt')},'Wiederherstellen')}catch(e){toast(e.message||'Sicherung ist ungültig.')}}
function settings(){return title('Dein Unternehmen','Angaben für deine Rechnungen, Angebote und Zahlungsinformationen.')+`<section class="card mini-form"><form onsubmit="saveProfile(event)"><div class="form-grid"><div class="full">${field('Unternehmensname / vollständiger Name','name','text',db.profile.name,'required maxlength="150"')}</div><div class="full">${textField('Vollständige Anschrift','address',db.profile.address)}</div><div>${field('Steuernummer oder USt-IdNr.','taxid','text',db.profile.taxid,'maxlength="60"')}</div><div>${field('Kontakt-E-Mail','email','email',db.profile.email,'maxlength="150"')}</div><div>${field('Telefon','phone','tel',db.profile.phone,'maxlength="60"')}</div><div>${field('Name der Bank','bank','text',db.profile.bank,'maxlength="100"')}</div><div>${field('IBAN','iban','text',db.profile.iban,'maxlength="34"')}</div><div>${field('BIC','bic','text',db.profile.bic,'maxlength="11"')}</div><div>${field('Rechnungsnummer-Präfix','prefix','text',db.profile.prefix,'required pattern="[A-Za-z0-9]{1,10}" maxlength="10"')}</div><div>${field('Angebotsnummer-Präfix','quotePrefix','text',db.profile.quotePrefix,'required pattern="[A-Za-z0-9]{1,10}" maxlength="10"')}</div><div>${field('Rücklagenziel (%)','reserve','number',db.profile.reserve,'required min="0" max="100"')}</div></div><div class="checkbox-line"><input id="profile-small" name="small" type="checkbox" ${db.profile.small?'checked':''}><label for="profile-small">Kleinunternehmerregelung für neue Dokumente vorbelegen</label></div><div class="actions"><button class="primary">Unternehmensprofil speichern</button></div></form></section><section class="card mini-form" style="margin-top:22px"><h2>Zentrale Datenhaltung & lokale Sicherungen</h2><p style="margin-top:15px">Der Arbeitsbereich und Originaldateien werden kontogetrennt zentral gespeichert. Der Speicherstatus zeigt ausstehende Änderungen und Konflikte. Lokale Browsercaches und heruntergeladene Sicherungen bleiben auf deinem Gerät. Erstelle zusätzlich regelmäßige vollständige Sicherungen.</p><div class="buttonrow"><button onclick="go('Vorlagen')">Logo & Vorlagen gestalten</button><button onclick="go('Exporte')">Sicherung & Wiederherstellung</button></div></section>`}
function saveProfile(e){e.preventDefault();const f=new FormData(e.target),p={...db.profile};for(const name of ['name','address','taxid','email','phone','bank','iban','bic','prefix','quotePrefix'])p[name]=f.get(name).trim();if(!p.name||!p.address){toast('Name und vollständige Anschrift sind erforderlich.');return}if(!/^[A-Za-z0-9]{1,10}$/.test(p.prefix)||!/^[A-Za-z0-9]{1,10}$/.test(p.quotePrefix)||p.prefix===p.quotePrefix){toast('Verwende unterschiedliche Präfixe aus 1–10 Buchstaben/Ziffern.');return}if(p.iban&&!validIBAN(p.iban)){toast('Die IBAN-Prüfsumme ist ungültig.');return}p.iban=p.iban.replace(/\s/g,'').toUpperCase();p.small=f.has('small');p.reserve=Number(f.get('reserve'));db.profile=p;if(save('Unternehmensprofil gespeichert'))toast('Profil gespeichert · freigegebene Dokumente bleiben unverändert')}
function validIBAN(s){s=s.replace(/\s/g,'').toUpperCase();if(!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(s))return false;if(s.startsWith('DE')&&s.length!==22)return false;const n=(s.slice(4)+s.slice(0,4)).replace(/[A-Z]/g,c=>String(c.charCodeAt(0)-55));let r=0;for(const d of n)r=(r*10+Number(d))%97;return r===1}
function legal(){return title('Funktionen & Grenzen','Was dieser Arbeitsbereich kann – und welche Anbindungen fehlen.')+`<section class="card"><h2>Zentrale Dokumentenverwaltung mit Kontoberechtigungen</h2><p style="margin-top:15px">Rechnungen und Angebote mit mehreren Positionen, eigene Vorlagen und Firmenbilder, unveränderbare Dokumentstände innerhalb der App, Teilzahlungen, Stornorechnungen, lokale Originalbelege, Bank-CSV-Abgleich, Exporte und Wiederherstellung sind implementiert.</p><div class="notice">Die zentrale Kontoverwaltung bietet Rollen und Zugriffsschutz, aber kein revisionssicheres Archiv. Technisch versierte Nutzer können lokale Browsercaches verändern. Eine vollständige Steuer- und Buchhaltungssoftware mit bestätigter Rechtssicherheit entsteht erst nach weiterem Ausbau und fachlicher Prüfung.</div><div class="report-grid"><section><h3>Rechnungen & Vorlagen</h3><p>Unterstützt einfache inländische Standardleistungen und § 19-Auswahl. Ausdruck/PDF ist keine strukturierte E-Rechnung. Die fachliche Zulässigkeit des Formats und der Angaben ist je Fall zu prüfen. Keine automatische Versendung.</p></section><section><h3>ELSTER & Steuern</h3><p>Vorbereitungslisten und Zahlungsübersichten sind nutzbar. Es gibt keine amtlichen Steuerformulare, vollständige Steuerberechnung oder ELSTER-Übermittlung.</p></section><section><h3>Banking</h3><p>CSV-Import und manuelle Zuordnung funktionieren lokal. Kein automatischer Bankabruf, keine Überweisungen und keine Kontoeröffnung.</p></section><section><h3>Wissensassistent</h3><p>Lokale Hilfesuche mit offiziellen Quellen. Kein KI-Dienst und keine individuelle Steuerberatung.</p></section></div><div class="buttonrow"><button onclick="go('Vorlagen')">Vorlagen</button><button onclick="go('Exporte')">Daten sichern</button></div></section><section class="card sources" style="margin-top:22px"><h2>Offizielle Grundlagen</h2><ul><li><a href="https://www.gesetze-im-internet.de/ustg_1980/__14.html" target="_blank" rel="noopener">§ 14 UStG: Rechnungsanforderungen</a></li><li><a href="https://www.gesetze-im-internet.de/ustg_1980/__19.html" target="_blank" rel="noopener">§ 19 UStG: Kleinunternehmer</a></li><li><a href="https://www.bundesfinanzministerium.de/Content/DE/FAQ/e-rechnung.html" target="_blank" rel="noopener">BMF: E-Rechnung und Übergangsregeln</a></li><li><a href="https://www.elster.de/elsterweb/infoseite/entwickler" target="_blank" rel="noopener">ELSTER: Schnittstellen für Entwickler</a></li></ul><p>Unabhängige App, keine Verbindung zu Accountable. Rechtsstand im Einzelfall prüfen.</p></section>`}
